import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import { call, t, formatNumber } from '../util';
/** The vote column: up, score, down, and the accept tick on answers. */
export default class Vote extends Component {
  busy = false;
  view() {
    const {
      post,
      discussion,
      question
    } = this.attrs;
    const vote = post.attribute('answersVote') || 0;
    const score = post.attribute('answersScore') || 0;
    const can = post.attribute('canAnswersVote') || !app.session.user;
    const accepted = discussion.attribute('answersAcceptedPostId') == post.id();
    const canAccept = !question && discussion.attribute('canAnswersAccept') && !post.isHidden();
    return m("div", {
      className: "Answers-vote"
    }, m("button", {
      type: "button",
      className: classList('Answers-voteButton', vote > 0 && 'is-on'),
      disabled: this.busy || !can,
      "aria-pressed": vote > 0 ? 'true' : 'false',
      "aria-label": t(question ? 'vote.up_question' : 'vote.up'),
      title: t(question ? 'vote.up_question' : 'vote.up'),
      onclick: () => this.cast(vote > 0 ? 0 : 1)
    }, m(Icon, {
      name: "fas fa-arrow-up"
    })), m("span", {
      className: "Answers-score",
      "aria-label": t('vote.score', {
        count: score
      })
    }, formatNumber(score)), m("button", {
      type: "button",
      className: classList('Answers-voteButton', vote < 0 && 'is-on'),
      disabled: this.busy || !can,
      "aria-pressed": vote < 0 ? 'true' : 'false',
      "aria-label": t(question ? 'vote.down_question' : 'vote.down'),
      title: t(question ? 'vote.down_question' : 'vote.down'),
      onclick: () => this.cast(vote < 0 ? 0 : -1)
    }, m(Icon, {
      name: "fas fa-arrow-down"
    })), canAccept ? m("button", {
      type: "button",
      className: classList('Answers-accept', accepted && 'is-on'),
      disabled: this.busy,
      "aria-pressed": accepted ? 'true' : 'false',
      "aria-label": t(accepted ? 'vote.unaccept' : 'vote.accept'),
      title: t(accepted ? 'vote.unaccept' : 'vote.accept'),
      onclick: () => this.accept(!accepted)
    }, m(Icon, {
      name: "fas fa-check"
    })) : accepted && m("span", {
      className: "Answers-accept is-on is-static",
      title: t('vote.accepted'),
      "aria-label": t('vote.accepted')
    }, m(Icon, {
      name: "fas fa-check"
    })));
  }
  cast(value) {
    if (!app.session.user) {
      app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
      return;
    }
    this.busy = true;
    call('POST', `/answers/posts/${this.attrs.post.id()}/vote`, {
      value
    }).then(r => this.attrs.post.pushAttributes({
      answersScore: r.score,
      answersVote: r.vote
    })).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  accept(on) {
    const {
      discussion,
      post
    } = this.attrs;
    this.busy = true;
    call('POST', `/answers/discussions/${discussion.id()}/accept`, {
      postId: on ? post.id() : null
    }).then(r => discussion.pushAttributes({
      answersAcceptedPostId: r.acceptedPostId,
      answersState: r.state,
      answersBounty: 0
    })).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-answers', 'forum/components/Vote', Vote);