import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import stringToColor from 'flarum/common/utils/stringToColor';
import { call, t, formatNumber } from '../util';
const cache = new Map();

/** (The attribute is qaTag: a component attribute named `tag` never arrives.)
 *  "Top helpers in Plugins": a card in the tag's sidebar, a scrolling strip above its list on phones. */
export default class Helpers extends Component {
  rows = null;
  oninit(vnode) {
    super.oninit(vnode);
    const slug = this.attrs.qaTag.slug();
    if (!cache.has(slug)) cache.set(slug, call('GET', '/answers/helpers?tag=' + encodeURIComponent(slug)).then(r => r.data).catch(() => []));
    cache.get(slug).then(rows => {
      this.rows = rows;
      m.redraw();
    });
  }
  view() {
    if (!this.rows || !this.rows.length) return m("div", {
      className: "Answers-helpers is-empty"
    });
    return m("div", {
      className: classList('Answers-helpers', 'Answers-helpers--' + this.attrs.place)
    }, m("h4", {
      className: "Answers-helpersTitle"
    }, t('helpers.title', {
      tag: this.attrs.qaTag.name()
    })), m("ol", {
      className: "Answers-helpersList"
    }, this.rows.map((row, i) => m("li", null, m(Link, {
      className: "Answers-helper",
      href: app.route('user', {
        username: row.slug
      })
    }, m("span", {
      className: "Answers-helperRank"
    }, i + 1), row.avatarUrl ? m("img", {
      className: "Avatar",
      src: row.avatarUrl,
      alt: "",
      loading: "lazy"
    }) : m("span", {
      className: "Avatar",
      style: {
        '--avatar-bg': '#' + stringToColor(row.displayName)
      }
    }, row.displayName.charAt(0).toUpperCase()), m("span", {
      className: "Answers-helperName"
    }, row.displayName), m("span", {
      className: "Answers-helperPoints"
    }, formatNumber(row.points)))))));
  }
}
flarum.reg.add('ernestdefoe-answers', 'forum/components/Helpers', Helpers);