import Component from 'flarum/common/Component';
import CommentPost from 'flarum/forum/components/CommentPost';
import classList from 'flarum/common/utils/classList';
import Vote from './Vote';
import Comments from './Comments';
/**
 * One question or answer: the vote column beside core's own CommentPost (so
 * edits, controls, likes, reactions and other extensions' parts all work as
 * on any post), with its comment thread underneath.
 */
export default class AnswerBlock extends Component {
  view() {
    const {
      post,
      discussion,
      question,
      accepted,
      highlight
    } = this.attrs;
    return m("div", {
      className: classList('AnswersPost', question && 'AnswersPost--question', accepted && 'AnswersPost--accepted', highlight && 'is-highlighted'),
      "data-id": post.id(),
      "data-number": post.number()
    }, m(Vote, {
      post: post,
      discussion: discussion,
      question: question
    }), m("div", {
      className: "AnswersPost-main"
    }, m(CommentPost, {
      post: post
    }), !post.isHidden() && discussion.attribute('answersComments') !== false && m(Comments, {
      post: post,
      discussion: discussion
    })));
  }
}
flarum.reg.add('ernestdefoe-answers', 'forum/components/AnswerBlock', AnswerBlock);