import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { call, t } from '../util';
const cache = new Map();

/**
 * "Is this your question?" under the composer's title: solved questions with
 * similar titles, once the title is 12 characters long, a moment after typing
 * stops (one request at a time, answers cached per title).
 */
export default class Similar extends Component {
  rows = [];
  asked = '';
  timer = null;
  dismissed = false;
  onremove(vnode) {
    super.onremove(vnode);
    if (this.timer) clearTimeout(this.timer);
  }
  view() {
    const title = (this.attrs.title() || '').trim();
    if (title !== this.asked) this.schedule(title);
    if (this.dismissed || !this.rows.length) return m("div", {
      className: "Answers-similar is-empty"
    });
    return m("div", {
      className: "Answers-similar",
      role: "region",
      "aria-label": t('similar.title')
    }, m("div", {
      className: "Answers-similarHead"
    }, m(Icon, {
      name: "far fa-lightbulb"
    }), m("strong", null, t('similar.title')), m("button", {
      type: "button",
      className: "Answers-linkButton",
      onclick: () => this.dismissed = true
    }, t('similar.dismiss'))), m("ul", null, this.rows.map(row => m("li", null, m(Icon, {
      name: "fas fa-check",
      className: "Answers-similarCheck"
    }), m(Link, {
      href: app.route('discussion', {
        id: row.id + (row.slug ? '-' + row.slug : '')
      }),
      external: true,
      target: "_blank",
      rel: "noopener"
    }, row.title), m("span", {
      className: "Answers-similarCount"
    }, t('similar.answers', {
      count: row.answers
    }))))));
  }
  schedule(title) {
    this.asked = title;
    if (this.timer) clearTimeout(this.timer);
    if (title.length < 12) {
      this.rows = [];
      return;
    }
    if (cache.has(title)) {
      this.rows = cache.get(title);
      return;
    }
    this.timer = window.setTimeout(() => {
      call('GET', '/answers/similar?q=' + encodeURIComponent(title)).then(r => {
        cache.set(title, r.data);
        if (this.asked === title) this.rows = r.data;
      }).catch(() => {}).finally(() => m.redraw());
    }, 400);
  }
}
flarum.reg.add('ernestdefoe-answers', 'forum/components/Similar', Similar);