import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { call, t } from '../util';
/** Suggest an edit to someone's answer: it goes to the review queue, and is applied when approved. */
export default class SuggestModal extends FormModal {
  source = null;
  text = '';
  summary = '';
  oninit(vnode) {
    super.oninit(vnode);
    call('GET', `/answers/posts/${this.attrs.post.id()}/revisions`).then(r => {
      this.source = r.source || '';
      this.text = this.source;
      m.redraw();
    });
  }
  className() {
    return 'Answers-suggestModal Modal--large';
  }
  title() {
    return t('suggest.title');
  }
  content() {
    if (this.source === null) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('suggest.help')), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "answers-suggest-text"
    }, t('suggest.text')), m("textarea", {
      id: "answers-suggest-text",
      name: "content",
      className: "FormControl",
      rows: 10,
      value: this.text,
      oninput: e => this.text = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "answers-suggest-summary"
    }, t('suggest.summary')), m("input", {
      id: "answers-suggest-summary",
      className: "FormControl",
      maxlength: 200,
      value: this.summary,
      placeholder: t('suggest.summary_placeholder'),
      oninput: e => this.summary = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading,
      disabled: this.text.trim() === this.source.trim()
    }, t('suggest.submit'))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    call('POST', `/answers/posts/${this.attrs.post.id()}/suggest`, {
      content: this.text,
      summary: this.summary
    }, true).then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('suggest.sent'));
    }).catch(error => this.onerror(error)).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-answers', 'forum/components/SuggestModal', SuggestModal);